<script setup>
import{computed,onBeforeUnmount,ref}from'vue'
const props=defineProps({action:{type:Object,required:true}}),emit=defineEmits(['complete']);const elapsed=ref(0),running=ref(false),done=ref(false);let timer
const total=computed(()=>props.action.phases.reduce((sum,p)=>sum+p.seconds,0)),phaseIndex=computed(()=>{let sum=0;for(let i=0;i<props.action.phases.length;i++){sum+=props.action.phases[i].seconds;if(elapsed.value<sum)return i}return props.action.phases.length-1}),phase=computed(()=>props.action.phases[phaseIndex.value]),phaseElapsed=computed(()=>elapsed.value-props.action.phases.slice(0,phaseIndex.value).reduce((sum,p)=>sum+p.seconds,0)),phaseRemaining=computed(()=>Math.max(0,phase.value.seconds-phaseElapsed.value)),progress=computed(()=>Math.min(100,elapsed.value/total.value*100)),remaining=computed(()=>Math.max(0,total.value-elapsed.value))
function start(){if(done.value)reset();if(running.value)return;running.value=true;timer=setInterval(()=>{elapsed.value++;if(elapsed.value>=total.value){pause();done.value=true}},1000)}function pause(){running.value=false;clearInterval(timer)}function reset(){pause();elapsed.value=0;done.value=false}function finish(){if(!done.value)return;emit('complete',{actionId:props.action.id,actionName:props.action.name});done.value=false}onBeforeUnmount(pause)
</script>
<template><div class="guided-movement"><div class="movement-guide-visual"><span>{{action.icon}}</span><strong>{{done?'完成':phase.title}}</strong><p>{{done?'慢慢停下来，感受一下现在的身体。':phase.tip}}</p></div><div class="movement-timer"><strong>{{done?'✓':phaseRemaining}}</strong><span>{{done?'已经走完这段练习':'当前动作剩余秒数'}}</span></div><div class="guide-progress"><i :style="{width:`${progress}%`}"></i></div><div class="guide-meta"><span>总进度 {{Math.round(progress)}}%</span><span>剩余 {{Math.ceil(remaining/60)}} 分钟</span></div><div class="guide-controls"><button v-if="!done" class="primary-button" type="button" @click="running?pause():start()">{{running?'暂停':elapsed?'继续':action.startLabel}}</button><button v-if="!done" class="secondary-button" type="button" @click="reset">重新开始</button><button v-else class="care-done-button" type="button" @click="finish">我做完了</button></div></div></template>
